import React, { useEffect, useState, useMemo } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import sorsuLogo from "../assets/sorsu-logo.png";

const API_URL = "http://localhost:5000";

const THEME = {
  primary: "#B11226",
  primaryDark: "#8E0E1E",
  background: "#F8F9FA",
  white: "#FFFFFF",
  textDark: "#1F2937",
  lightGray: "#E5E7EB",
};

function VotingPage({ auth }) {
  const [candidates, setCandidates] = useState([]);
  const [selected, setSelected] = useState({});
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [hasVoted, setHasVoted] = useState(false);

  const [showModal, setShowModal] = useState(false);
  const [modalMessage, setModalMessage] = useState("");
  const [modalType, setModalType] = useState("confirm");

  const navigate = useNavigate();

  // ✅ Fetch candidates + user votes
  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const resCandidates = await axios.get(`${API_URL}/api/candidates`);
        setCandidates(resCandidates.data);

        if (auth?.token) {
          const resVotes = await axios.get(`${API_URL}/api/vote/my`, {
            headers: { Authorization: `Bearer ${auth.token}` },
          });

          const selectedVotes = {};
          resVotes.data.forEach((v) => {
            selectedVotes[v.position] = v.candidateId;
          });

          setSelected(selectedVotes);

          if (resVotes.data.length > 0) setHasVoted(true);
        }
      } catch (err) {
        console.error(err);
        setModalType("error");
        setModalMessage("Failed to load candidates or votes.");
        setShowModal(true);
      }
      setLoading(false);
    };

    fetchData();
  }, [auth]);

  // ✅ Group by position
  const groupedCandidates = useMemo(() => {
    return candidates.reduce((groups, candidate) => {
      const position = candidate.candidacy;
      if (!groups[position]) groups[position] = [];
      groups[position].push(candidate);
      return groups;
    }, {});
  }, [candidates]);

  const handleSelect = (position, candidateId) => {
    if (hasVoted) return;
    setSelected((prev) => ({
      ...prev,
      [position]: prev[position] === candidateId ? null : candidateId,
    }));
  };

  // ✅ Trigger confirm modal
  const handleCastVote = () => {
    if (!auth?.token) {
      setModalType("error");
      setModalMessage("You must be logged in to vote.");
      setShowModal(true);
      return;
    }

    if (Object.values(selected).filter(Boolean).length === 0) {
      setModalType("error");
      setModalMessage("Please select a candidate first.");
      setShowModal(true);
      return;
    }

    setModalType("confirm");
    setModalMessage("Are you sure you want to cast your vote?");
    setShowModal(true);
  };

  // ✅ FINAL FIXED VOTE FLOW
  const confirmVote = async () => {
    try {
      setSubmitting(true);

      await axios.post(
        `${API_URL}/api/votes/batch`,
        { candidateIds: Object.values(selected).filter(Boolean) },
        { headers: { Authorization: `Bearer ${auth.token}` } }
      );

      setHasVoted(true);
      setSelected({});
      setShowModal(false);

      // ✅ REDIRECT IMMEDIATELY
      navigate("/my-votes", { state: { justVoted: true } });

    } catch (err) {
      console.error(err);
      setModalType("error");
      setModalMessage(
        err.response?.data?.message || "Vote failed. Please try again."
      );
      setShowModal(true);
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) return <div style={{ padding: 50 }}>Loading candidates...</div>;

  return (
    <div style={{ backgroundColor: THEME.background, minHeight: "100vh" }}>
      {/* HEADER */}
      <div
        style={{
          width: "100%",
          background: `linear-gradient(to right, ${THEME.primary}, ${THEME.primaryDark})`,
          color: "white",
          textAlign: "center",
          padding: "20px 0",
          fontWeight: "bold",
          fontSize: 22,
        }}
      >
        <img src={sorsuLogo} alt="SorSU Logo" style={{ height: 50, marginRight: 10 }} />
        OFFICIAL CANDIDATES LIST 2026
      </div>

      {/* CANDIDATES */}
      <div style={{ padding: 60, maxWidth: 1300, margin: "auto" }}>
        {Object.entries(groupedCandidates).map(([position, list]) => (
          <div key={position} style={{ marginBottom: 60 }}>
            <h2
              style={{
                marginBottom: 30,
                color: THEME.primary,
                borderLeft: `6px solid ${THEME.primary}`,
                paddingLeft: 15,
              }}
            >
              {position}
            </h2>

            <div style={{ display: "flex", gap: 20, overflowX: "auto" }}>
              {list.map((candidate) => {
                const isSelected = selected[position] === candidate._id;

                return (
                  <div
                    key={candidate._id}
                    onClick={() => handleSelect(position, candidate._id)}
                    style={{
                      width: 240,
                      backgroundColor: THEME.white,
                      borderRadius: 15,
                      padding: 20,
                      cursor: hasVoted ? "not-allowed" : "pointer",
                      opacity: hasVoted ? 0.6 : 1,
                      border: isSelected
                        ? `4px solid ${THEME.primary}`
                        : "2px solid transparent",
                      boxShadow: isSelected
                        ? "0 15px 30px rgba(177,18,38,0.3)"
                        : "0 10px 25px rgba(0,0,0,0.05)",
                    }}
                  >
                    {candidate.image ? (
                      <img
                        src={`${API_URL}/uploads/${candidate.image}`}
                        alt=""
                        style={{
                          width: "100%",
                          height: 180,
                          objectFit: "cover",
                          borderRadius: 10,
                          marginBottom: 12,
                        }}
                      />
                    ) : (
                      <div style={{ height: 180, background: "#ddd", borderRadius: 10 }} />
                    )}

                    <h3>{candidate.firstName} {candidate.lastName}</h3>
                    <p><strong>Course:</strong> {candidate.course || "N/A"}</p>
                    <p><strong>Year:</strong> {candidate.yearLevel || "N/A"}</p>
                    <p><strong>Party:</strong> {candidate.partylist || "Independent"}</p>
                  </div>
                );
              })}
            </div>
          </div>
        ))}

        {!hasVoted && (
          <div style={{ textAlign: "center", marginTop: 40 }}>
            <button
              onClick={handleCastVote}
              disabled={submitting}
              style={{
                padding: "15px 40px",
                fontSize: 18,
                fontWeight: "bold",
                backgroundColor: THEME.primary,
                color: "white",
                border: "none",
                borderRadius: 10,
                cursor: "pointer",
              }}
            >
              {submitting ? "Submitting..." : "Cast Vote"}
            </button>
          </div>
        )}
      </div>

      {/* MODAL */}
      {showModal && (
        <div style={modalStyles.overlay}>
          <div style={modalStyles.modal}>
            <h3>{modalType === "confirm" ? "Confirm Vote" : "Error"}</h3>
            <p>{modalMessage}</p>

            {modalType === "confirm" ? (
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <button style={modalStyles.cancel} onClick={() => setShowModal(false)}>
                  Cancel
                </button>
                <button style={modalStyles.confirm} onClick={confirmVote}>
                  Confirm
                </button>
              </div>
            ) : (
              <button style={modalStyles.confirm} onClick={() => setShowModal(false)}>
                OK
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

const modalStyles = {
  overlay: {
    position: "fixed",
    top: 0,
    left: 0,
    width: "100%",
    height: "100%",
    backgroundColor: "rgba(0,0,0,0.6)",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
  },
  modal: {
    width: 350,
    backgroundColor: "#fff",
    padding: 25,
    borderRadius: 10,
    textAlign: "center",
  },
  cancel: {
    padding: "10px 20px",
    backgroundColor: "#ccc",
    border: "none",
    borderRadius: 6,
  },
  confirm: {
    padding: "10px 20px",
    backgroundColor: "#B11226",
    color: "#fff",
    border: "none",
    borderRadius: 6,
  },
};

export default VotingPage;
